private static PermissionDecider.Request recoveredPermission(
        SessionDocument current, CanonicalSessionState.Permission permission, Content.ToolCall call) {
    SessionDocument.Record prepared = current.records().stream()
            .filter(record -> record.kind() == SessionDocument.RecordKind.TOOL_PREPARED)
            .filter(record -> permission.toolExecutionId().value()
                    .equals(record.data().get("toolExecutionId")))
            .findFirst().orElseThrow(() -> new IllegalStateException(
                    "durable Permission risk snapshot is missing"));
    Map<String, Object> data = prepared.data();
    if (!permission.id().value().equals(data.get("permissionId"))) {
        throw new IllegalStateException("durable Permission identity is invalid");
    }
    String workspaceId = text(data, "workspaceId");
    long workspaceGeneration = number(data, "workspaceGeneration");
    PermissionDecider.RiskLevel riskLevel;
    try {
        riskLevel = PermissionDecider.RiskLevel.valueOf(text(data, "riskLevel"));
    } catch (IllegalArgumentException failure) {
        throw new IllegalStateException("durable Permission risk level is invalid", failure);
    }
