    Instant expiresAt;
    try {
        createdAt = Instant.parse(text(data, "permissionCreatedAt"));
        expiresAt = Instant.parse(text(data, "permissionExpiresAt"));
    } catch (java.time.format.DateTimeParseException failure) {
        throw new IllegalStateException("durable Permission time is invalid", failure);
    }
    if (!expiresAt.equals(permission.expiresAt())) {
        throw new IllegalStateException("durable Permission expiry is inconsistent");
    }
    long requestRevision = permission.status() == CanonicalSessionState.PermissionStatus.PENDING
            ? permission.revision() : Math.max(0, permission.revision() - 1);
    return new PermissionDecider.Request(
            permission.id().value(), "embedded", permission.sessionId().value(), "embedded",
            new WorkspaceProvider.WorkspaceIdentity(workspaceId, workspaceGeneration),
            call.id(), call.name(), call.arguments(),
            new PermissionDecider.Risk(riskLevel, text(data, "riskRuleId")), requestRevision,
            createdAt, expiresAt);
}

private static String text(Map<String, Object> data, String name) {
    Object value = data.get(name);
    if (value instanceof String text && !text.isBlank()) return text;
    throw new IllegalStateException("durable field is invalid: " + name);
}

